const __pageData = JSON.parse('{"title":"Saudi Arabia","description":"","frontmatter":{"title":"Saudi Arabia","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["saudi-arabia","petrodollar","oil","media"],"sources":["raw/a-week-to-remember.md","raw/a-dereliction-of-duty.md","raw/and-iran-iran-so-far-away.md","raw/arabian-nights.md","raw/badlands-brief-05f.md","raw/badlands-brief-1c6.md","raw/badlands-brief-1ae.md","raw/badlands-brief-323.md","raw/badlands-brief-285.md","raw/badlands-brief-5a2.md","raw/badlands-brief-52f.md","raw/badlands-brief-625.md","raw/badlands-brief-71c.md","raw/badlands-brief-9ea.md","raw/badlands-brief-ac2.md","raw/badlands-brief-b56.md","raw/badlands-brief-bb1.md","raw/badlands-brief-be1.md","raw/badlands-brief-e15.md","raw/badlands-brief-e60.md","raw/badlands-brief-ea5.md","raw/badlands-brief-eea.md","raw/badlands-news-brief-048.md","raw/badlands-news-brief-079.md","raw/badlands-news-brief-0be.md","raw/badlands-news-brief-1a0.md","raw/badlands-news-brief-27c.md","raw/badlands-news-brief-426.md","raw/badlands-news-brief-4b3.md","raw/badlands-news-brief-582.md","raw/badlands-news-brief-6c1.md","raw/badlands-news-brief-745.md","raw/badlands-news-brief-7b8.md","raw/badlands-news-brief-85a.md","raw/badlands-news-brief-889.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/saudi-arabia.md","filePath":"entities/saudi-arabia.md","lastUpdated":null}');
